import catalogJson from '../../../data/catalog.vellore.json';

import type { Catalog } from './catalog';

// The JSON is generated by scripts/import-catalog.ts; the cast keeps the
// compiler from inferring a 450-course literal type.
export const catalog = catalogJson as unknown as Catalog;

export const courseByCode = new Map(catalog.courses.map((course) => [course.code, course]));
